// Inverse NTT for Dilithium (VLEN = 128) with Barrett multiplication, the counterpart of
// ntt_rvv_vlen128_barret_mul (ntt_dilithium_rvv_vlen128_barret_mul.s). Input in the order of that
// NTT (= upstream's NTT order), output as upstream's invntt_tomont: multiplied by 2^32, centered in
// (-q/2, q/2] like the Montgomery output of upstream's and PQRV's INTT. Keypair relies on that:
// t = intt(A*s1) + s2 must stay in (-q, q) for caddq/power2round.
// Gentleman-Sande butterflies with plain roots (include/intt_dilithium_1234_5678_twiddles_barret_mul.s).
// layer8765: 16 blocks of 16 coefficients; levels 8, 7 (len 1, 2) on the transposed block
// (vlseg4e32), then levels 6, 5 (len 4, 8).
// layer4321: 4 x 64 coefficients (as layer1234 of the NTT); levels 4, 3, 2 (len 16, 32, 64) and
// level 1 (len 128) merged with the scaling by 2^32 / 256, then centered.
// Bounds: as in upstream's invntt_tomont the sums are not reduced (|input| < q rules out overflow);
// Barrett products are in (-q/4, 5q/4).
// Uses only caller-saved scalar registers, so nothing is saved. The SLOTHY config reserves the
// callee-saved ones (CALLEE_SAVED in _example.py), so the opt version keeps this. Loop counter:
// t2 (an ABI name, as SLOTHY's loop detection requires).

    #define in        x10
    // == a0, first function arg (a1, the twiddle pointer, is not used)
    #define root_ptr  x5
    #define modulus   x6
    #define xhalf     x11
    // (q-1)/2 for center, set before layer4321 (a1, the unused twiddle pointer)

    #define data0  v0
    #define data1  v1
    #define data2  v2
    #define data3  v3
    #define data4  v4
    #define data5  v5
    #define data6  v6
    #define data7  v7
    #define data8  v8
    #define data9  v9
    #define data10 v10
    #define data11 v11
    #define data12 v12
    #define data13 v13
    #define data14 v14
    #define data15 v15

    #define vtmp0  v16
    // used by barret_mul
    #define vtmp1  v17
    // used by gs_butterfly, gs_butterfly_scale, center
    #define vtmp2  v18
    // used by gs_butterfly_scale

    // layer8765: twiddles of one block
    #define vroot1      v19
    #define vbarretc_1  v20
    #define vroot2      v21
    #define vbarretc_2  v22
    #define vroot3      v23
    #define vbarretc_3  v24
    #define xroot1      x12
    #define xbarretc_1  x13
    #define xroot2      x14
    #define xbarretc_2  x15
    #define xroot3      x16
    #define xbarretc_3  x17

    // layer4321: twiddles, loaded on demand
    #define xroot       x28
    #define xbarretc    x29
    #define xroot_f     x30
    #define xbarretc_f  x31

.macro barret_mul dst, a, b, barret_const
    vmul.vx \dst, \a, \b                            // z = a*b = coefficient (vect) * root (scalar)
    vmulh.vx vtmp0, \a, \barret_const               // t = (a * barret_const) >> 32
    vnmsac.vx \dst, modulus, vtmp0                  // z = z - n * t
.endm

.macro barret_mul_v vdst, va, vb, vbarret_const
    vmul.vv \vdst, \va, \vb                         // z = a*b = coefficient (vect) * root (vect)
    vmulh.vv vtmp0, \va, \vbarret_const             // t = (a * barret_const) >> 32
    vnmsac.vx \vdst, modulus, vtmp0                 // z = z - n * t
.endm

.macro gs_butterfly a, b, root, barret_const
    vsub.vv vtmp1, \a, \b                           // vtmp1 = a - b
    vadd.vv \a, \a, \b                              // a = a + b
    barret_mul \b, vtmp1, \root, \barret_const      // b = (a - b) * root mod modulus
.endm

.macro gs_butterfly_v va, vb, vroot, vbarret_const
    vsub.vv vtmp1, \va, \vb                         // vtmp1 = a - b
    vadd.vv \va, \va, \vb                           // a = a + b
    barret_mul_v \vb, vtmp1, \vroot, \vbarret_const // b = (a - b) * root mod modulus
.endm

// last level, merged with the final scaling: a = (a + b) * f, b = (a - b) * root * f
.macro gs_butterfly_scale a, b, root_f, barret_const, f, barret_const_f
    vadd.vv vtmp1, \a, \b                           // vtmp1 = a + b
    vsub.vv vtmp2, \a, \b                           // vtmp2 = a - b
    barret_mul \a, vtmp1, \f, \barret_const_f
    barret_mul \b, vtmp2, \root_f, \barret_const
.endm

// a = a > (q-1)/2 ? a - modulus : a: (-q/4, 5q/4) -> (-q/2, q/2]
.macro center a
    vrsub.vx vtmp1, \a, xhalf                       // vtmp1 = (q-1)/2 - a
    vsra.vi vtmp1, vtmp1, 31                        // vtmp1 = a > (q-1)/2 ? -1 : 0
    vand.vx vtmp1, vtmp1, modulus                   // vtmp1 = a > (q-1)/2 ? q : 0
    vsub.vv \a, \a, vtmp1
.endm

.macro transpose4 data, ptr
    vsseg4e32.v \data, (\ptr)   // @slothy:writes=["'transpose_buf'"]
    vl4re32.v   \data, (\ptr)   // @slothy:reads=["'transpose_buf'"]
.endm

.macro load16 in, stride
    vle32.v data0, (\in)
    addi \in, \in, \stride
    vle32.v data1, (\in)
    addi \in, \in, \stride
    vle32.v data2, (\in)
    addi \in, \in, \stride
    vle32.v data3, (\in)
    addi \in, \in, \stride
    vle32.v data4, (\in)
    addi \in, \in, \stride
    vle32.v data5, (\in)
    addi \in, \in, \stride
    vle32.v data6, (\in)
    addi \in, \in, \stride
    vle32.v data7, (\in)
    addi \in, \in, \stride
    vle32.v data8, (\in)
    addi \in, \in, \stride
    vle32.v data9, (\in)
    addi \in, \in, \stride
    vle32.v data10, (\in)
    addi \in, \in, \stride
    vle32.v data11, (\in)
    addi \in, \in, \stride
    vle32.v data12, (\in)
    addi \in, \in, \stride
    vle32.v data13, (\in)
    addi \in, \in, \stride
    vle32.v data14, (\in)
    addi \in, \in, \stride
    vle32.v data15, (\in)
.endm

.macro store16 in, stride
    vse32.v data0, (\in)
    addi \in, \in, \stride
    vse32.v data1, (\in)
    addi \in, \in, \stride
    vse32.v data2, (\in)
    addi \in, \in, \stride
    vse32.v data3, (\in)
    addi \in, \in, \stride
    vse32.v data4, (\in)
    addi \in, \in, \stride
    vse32.v data5, (\in)
    addi \in, \in, \stride
    vse32.v data6, (\in)
    addi \in, \in, \stride
    vse32.v data7, (\in)
    addi \in, \in, \stride
    vse32.v data8, (\in)
    addi \in, \in, \stride
    vse32.v data9, (\in)
    addi \in, \in, \stride
    vse32.v data10, (\in)
    addi \in, \in, \stride
    vse32.v data11, (\in)
    addi \in, \in, \stride
    vse32.v data12, (\in)
    addi \in, \in, \stride
    vse32.v data13, (\in)
    addi \in, \in, \stride
    vse32.v data14, (\in)
    addi \in, \in, \stride
    vse32.v data15, (\in)
.endm

